-- DetaurBar_Data.lua
-- Handles data storage, list management, and completion states.
-- ItemDatabase is now in DetaurBar_ItemDB.lua (generated by parse_itemcache.py)

-- Global namespace
DetaurBar = DetaurBar or {}
DetaurBar.Data = {}

-- Helper to shift time by 3 hours so that midnight of shifted time is 3:00 AM of actual time
local function GetLogicalDay(timestamp)
    local shiftedTime = (timestamp or time()) - 10800
    return date("%Y-%m-%d", shiftedTime)
end

function DetaurBar.Data.InitializeDB()
    if not DetaurBarDB then
        DetaurBarDB = {}
    end
    if not DetaurBarDB.todo then
        DetaurBarDB.todo = {}
    end
    if not DetaurBarDB.todo.day then DetaurBarDB.todo.day = {} end
    if not DetaurBarDB.todo.week then DetaurBarDB.todo.week = {} end
    if not DetaurBarDB.todo.month then DetaurBarDB.todo.month = {} end
    if not DetaurBarDB.tasks then
        DetaurBarDB.tasks = {
            categories = { "General" },
            data = {
                ["General"] = {},
            }
        }
    elseif not DetaurBarDB.tasks.categories then
        DetaurBarDB.tasks.categories = { "General" }
        DetaurBarDB.tasks.data = DetaurBarDB.tasks.data or {}
        for _, name in ipairs(DetaurBarDB.tasks.categories) do
            if not DetaurBarDB.tasks.data[name] then DetaurBarDB.tasks.data[name] = {} end
        end
    end
    if not DetaurBarDB.notes then
        DetaurBarDB.notes = {
            categories = { "General", "War", "Guild" },
            data = {
                ["General"] = {},
                ["War"] = {},
                ["Guild"] = {},
            }
        }
    elseif DetaurBarDB.notes.war or DetaurBarDB.notes.general or DetaurBarDB.notes.guild then
        local oldData = {}
        if DetaurBarDB.notes.general then oldData["General"] = DetaurBarDB.notes.general end
        if DetaurBarDB.notes.war then oldData["War"] = DetaurBarDB.notes.war end
        if DetaurBarDB.notes.guild then oldData["Guild"] = DetaurBarDB.notes.guild end
        DetaurBarDB.notes = {
            categories = { "General", "War", "Guild" },
            data = oldData,
        }
    elseif not DetaurBarDB.notes.categories then
        DetaurBarDB.notes.categories = { "General", "War", "Guild" }
        DetaurBarDB.notes.data = DetaurBarDB.notes.data or {}
        for _, name in ipairs(DetaurBarDB.notes.categories) do
            if not DetaurBarDB.notes.data[name] then DetaurBarDB.notes.data[name] = {} end
        end
    end
    if DetaurBarDB.buy and not DetaurBarDB.loot then
        DetaurBarDB.loot = DetaurBarDB.buy
        DetaurBarDB.buy = nil
    end
    if DetaurBarDB.loot and DetaurBarDB.loot[1] then
        DetaurBarDB.loot = { add = DetaurBarDB.loot, delete = {} }
    elseif DetaurBarDB.loot and not DetaurBarDB.loot.add then
        DetaurBarDB.loot = { add = {}, delete = {} }
    end
    if not DetaurBarDB.loot then
        DetaurBarDB.loot = { add = {}, refuse = {} }
    end
    if not DetaurBarDB.loot.add then DetaurBarDB.loot.add = {} end
