            task.completed = false
        end
        if DetaurBarDB.tasks and DetaurBarDB.tasks.data then
            for _, catName in ipairs(DetaurBarDB.tasks.categories) do
                local items = DetaurBarDB.tasks.data[catName]
                if items then
                    for _, item in ipairs(items) do
                        item.completed = false
                    end
                end
            end
        end
    end

    -- Clean up stale migration flags from previous buggy versions
    if DetaurBarDB._migratedHerbIds or DetaurBarDB._migratedHerbIdsV2 or DetaurBarDB._migratedHerbIdsV3 or DetaurBarDB._migratedHerbIdsFinal then
        DetaurBarDB._migratedHerbIds = nil
        DetaurBarDB._migratedHerbIdsV2 = nil
        DetaurBarDB._migratedHerbIdsV3 = nil
        DetaurBarDB._migratedHerbIdsFinal = nil
    end

    -- [MIGRATION 2026-07-06 v4] Fix shifted herb IDs in BOTH link items AND item:ID format.
    -- Warmane cache (2026-07): goldclover=36901, adder's tongue=36903, tiger lily=36904,
    -- lichbloom=36905, icethorn=36906, talandra's rose=36907, frost lotus=36908, fire leaf=39970
    -- Old WRONG DB had: frost lotus=36902, fire leaf=36903, adder's tongue=36905, lichbloom=36906, icethorn=36908
    local herbIdFix = {
        [36902] = 36908,  -- frost lotus
        [36903] = 39970,  -- fire leaf
        [36905] = 36903,  -- adder's tongue
        [36906] = 36905,  -- lichbloom
        [36908] = 36906,  -- icethorn
    }
    if not DetaurBarDB._migratedHerbIdsV4 then
        local function fixItemId(title)
            if title then
                -- Fix link format: |c...|Hitem:36908|h[Icethorn]|h|r  -> correct ID via name lookup
                local linkName = string.match(title, "%|h%[(.-)%]%|h")
                if linkName then
                    local cleaned = string.lower(linkName)
                    local correctId = DetaurBar.Data.ItemDatabase and DetaurBar.Data.ItemDatabase[cleaned]
                    if correctId then
                        local newTitle = string.gsub(title, "|Hitem:(%d+)", "|Hitem:" .. correctId)
                        if newTitle ~= title then
                            return newTitle
                        end
                    end
                end
                -- Fix item:ID format: "item:36902" -> "item:36908" via herbIdFix mapping
                local itemIdNum = tonumber(string.match(title, "^item:(%d+)$"))
                if itemIdNum and herbIdFix[itemIdNum] then
                    return "item:" .. herbIdFix[itemIdNum]
                end
            end
            return title
        end
        local function fixList(list)
            if list and type(list) == "table" then
                for _, item in ipairs(list) do
                    if item.title then
                        item.title = fixItemId(item.title)
                    end
                end
            end
        end
        fixList(DetaurBarDB.price)
        fixList(DetaurBarDB.sell)
        if DetaurBarDB.loot and type(DetaurBarDB.loot) == "table" then
            fixList(DetaurBarDB.loot.add)
            fixList(DetaurBarDB.loot.delete)
            fixList(DetaurBarDB.loot.refuse)
        end
        DetaurBarDB._migratedHerbIdsV4 = true
    end
end

function DetaurBar.Data.GetItems(category)
    DetaurBar.Data.InitializeDB()
    if category == "todo_day" then
        return DetaurBarDB.todo.day
    elseif category == "todo_week" then
        return DetaurBarDB.todo.week
    elseif category == "todo_month" then
        return DetaurBarDB.todo.month
    elseif category:find("^tasks_") then
        local catName = category:sub(7)
        for _, catDisplayName in ipairs(DetaurBarDB.tasks.categories) do
            if catDisplayName:lower() == catName then
                return DetaurBarDB.tasks.data[catDisplayName] or {}
            end
        end
        return {}
    elseif category:find("^notes_") then
        local catName = category:sub(7)
        for _, catDisplayName in ipairs(DetaurBarDB.notes.categories) do
            if catDisplayName:lower() == catName then
                return DetaurBarDB.notes.data[catDisplayName] or {}
            end
        end
        return {}
    elseif category == "loot_add" then
        return DetaurBarDB.loot.add
    elseif category == "loot_delete" then
        return DetaurBarDB.loot.delete
    elseif category == "sell" then
        return DetaurBarDB.sell
    elseif category == "price" then
        local faction = UnitFactionGroup("player") or "Unknown"
        if not DetaurBarDB.price[faction] then
            DetaurBarDB.price[faction] = {}
        end
        return DetaurBarDB.price[faction]
    elseif category == "recipes" then
        return DetaurBarDB.recipes
    end
    return {}
end

function DetaurBar.Data.AddItem(category, title, subCategory)
    DetaurBar.Data.InitializeDB()
    local items = DetaurBar.Data.GetItems(category)

    local newItem = {
        id = time() .. "_" .. tostring(math.random(1000, 9999)),
        title = title,
        completed = false,
        created = time(),
        subCategory = subCategory
    }

    table.insert(items, newItem)
    return newItem
end

function DetaurBar.Data.DeleteItem(category, id)
    DetaurBar.Data.InitializeDB()
    local items = DetaurBar.Data.GetItems(category)

    for i, item in ipairs(items) do
        if item.id == id then
            table.remove(items, i)
            return true
        end
    end
    return false
end

-- [RECIPES] AddRecipe — appends a recipe entry (with spellId, profession, reagents)
function DetaurBar.Data.AddRecipe(recipeData)
    DetaurBar.Data.InitializeDB()
    recipeData.id = recipeData.id or (time() .. "_" .. tostring(math.random(1000, 9999)))
    recipeData.created = recipeData.created or time()
    table.insert(DetaurBarDB.recipes, recipeData)
    return recipeData
end

-- [RECIPES] DeleteRecipe — removes recipe by id
function DetaurBar.Data.DeleteRecipe(id)
    DetaurBar.Data.InitializeDB()
    for i, recipe in ipairs(DetaurBarDB.recipes) do
        if recipe.id == id then
            table.remove(DetaurBarDB.recipes, i)
            return true
        end
    end
    return false
end

function DetaurBar.Data.ToggleTask(category, id)
    DetaurBar.Data.InitializeDB()
    local items = DetaurBar.Data.GetItems(category)
    for _, item in ipairs(items) do
        if item.id == id then
            item.completed = not item.completed
            return item.completed
        end
    end
    return nil
end

function DetaurBar.Data.GetItemById(category, id)
    DetaurBar.Data.InitializeDB()
    local items = DetaurBar.Data.GetItems(category)
    for _, item in ipairs(items) do
        if item.id == id then
            return item
        end
    end
    return nil
end

function DetaurBar.Data.MoveItem(fromCategory, toCategory, id)
    DetaurBar.Data.InitializeDB()
    local fromList = DetaurBar.Data.GetItems(fromCategory)
    local toList = DetaurBar.Data.GetItems(toCategory)

    for i, item in ipairs(fromList) do
        if item.id == id then
            local movingItem = table.remove(fromList, i)
            movingItem.completed = false
            table.insert(toList, movingItem)
            return true
        end
    end
    return false
end

function DetaurBar.Data.SavePricePoint(itemId, buyoutPerItem)
    DetaurBar.Data.InitializeDB()
    local faction = UnitFactionGroup("player") or "Unknown"
    local key = itemId .. ":" .. faction
    if not DetaurBarDB.priceHistory[key] then
        DetaurBarDB.priceHistory[key] = {}
    end
    DetaurBarDB.priceHistory[key][tostring(time())] = buyoutPerItem
end

function DetaurBar.Data.GetPriceHistory(itemId)
    DetaurBar.Data.InitializeDB()
    local faction = UnitFactionGroup("player") or "Unknown"
    local key = itemId .. ":" .. faction
    return DetaurBarDB.priceHistory[key] or {}
end

function DetaurBar.Data.GetBuySellHistory(itemId)
    DetaurBar.Data.InitializeDB()
    local faction = UnitFactionGroup("player") or "Unknown"
    local key = itemId .. ":" .. faction
    local raw = DetaurBarDB.buySellHistory[key]
    if not raw then return {} end
    local result = {}
    for _, record in ipairs(raw) do
        table.insert(result, record)
    end
    table.sort(result, function(a, b) return a.ts < b.ts end)
    return result
end

function DetaurBar.Data.IsItemInPriceList(itemId)
    DetaurBar.Data.InitializeDB()
    local faction = UnitFactionGroup("player") or "Unknown"
    local items = DetaurBarDB.price[faction]
    if not items then return false end
    local prefix = "item:" .. itemId
    for _, item in ipairs(items) do
        if item.title == prefix then return true end
    end
    return false
end

function DetaurBar.Data.RecordBuyTransaction(itemId, pricePerItem, quantity, timestamp)
    DetaurBar.Data.InitializeDB()
    if pricePerItem == 0 then
        local history = DetaurBar.Data.GetPriceHistory(itemId)
        local maxTs = 0
        for tsStr, price in pairs(history) do
            local ts = tonumber(tsStr)
            if ts and ts > maxTs then
                maxTs = ts
                pricePerItem = price
            end
        end
    end
    local faction = UnitFactionGroup("player") or "Unknown"
    local key = itemId .. ":" .. faction
    if not DetaurBarDB.buySellHistory[key] then
        DetaurBarDB.buySellHistory[key] = {}
    end
    table.insert(DetaurBarDB.buySellHistory[key], {
        ts = timestamp or time(),
        type = "buy",
        price = pricePerItem,
        quantity = quantity or 1,
    })
end

function DetaurBar.Data.RecordSellTransaction(itemId, pricePerItem, quantity, timestamp)
    DetaurBar.Data.InitializeDB()
    local faction = UnitFactionGroup("player") or "Unknown"
    local key = itemId .. ":" .. faction
    if not DetaurBarDB.buySellHistory[key] then
        DetaurBarDB.buySellHistory[key] = {}
    end
    table.insert(DetaurBarDB.buySellHistory[key], {
        ts = timestamp or time(),
        type = "sell",
        price = pricePerItem,
        quantity = quantity or 1,
    })
end

function DetaurBar.Data.DeletePricePoint(itemId, timestampStr)
    DetaurBar.Data.InitializeDB()
    local faction = UnitFactionGroup("player") or "Unknown"
    local key = itemId .. ":" .. faction
    DEFAULT_CHAT_FRAME:AddMessage("|cff888888[DEBUG] Delete: itemId=" .. tostring(itemId) .. " (" .. type(itemId) .. "), key=" .. tostring(key) .. ", ts=" .. tostring(timestampStr))
    if DetaurBarDB.priceHistory[key] then
        local before = DetaurBarDB.priceHistory[key][timestampStr]
        DetaurBarDB.priceHistory[key][timestampStr] = nil
        local after = DetaurBarDB.priceHistory[key][timestampStr]
        DEFAULT_CHAT_FRAME:AddMessage("|cff888888[DEBUG] before=" .. tostring(before) .. ", after=" .. tostring(after))
    else
        DEFAULT_CHAT_FRAME:AddMessage("|cffff0000[DEBUG] key not found: " .. tostring(key))
    end
end

function DetaurBar.Data.GetSettings()
    DetaurBar.Data.InitializeDB()
    return DetaurBarDB.settings
end

function DetaurBar.Data.IsSubTabVisible(tabType, subTabName)
    local settings = DetaurBar.Data.GetSettings()
    if tabType == "loot" then
        return settings.lootSubTabsVisible and settings.lootSubTabsVisible[subTabName] ~= false
    elseif tabType == "price" then
        return settings.priceSubTabsVisible and settings.priceSubTabsVisible[subTabName] ~= false
    elseif tabType == "alert" then
        return settings.alertSubTabsVisible and settings.alertSubTabsVisible[subTabName] ~= false
    end
    return true
end

function DetaurBar.Data.GetItemName(itemId)
    if not itemId then return nil end
    if DetaurBar.Data.ItemDatabaseReverse and DetaurBar.Data.ItemDatabaseReverse[itemId] then
        local name = DetaurBar.Data.ItemDatabaseReverse[itemId]
        return (name:sub(1,1):upper() .. name:sub(2)):gsub("(%s)(%a)", function(s, a) return s .. a:upper() end)
    end
    return (GetItemInfo(itemId))
end

-- Icon caching: tries static ItemIcons -> DetaurBarDB.iconCache -> GetItemInfo
-- If GetItemInfo succeeds, stores result in DB for next reload.
function DetaurBar.Data.GetItemTexture(itemId)
    if not itemId then return nil end
    if DetaurBar.Data.ItemIcons and DetaurBar.Data.ItemIcons[itemId] then
        return DetaurBar.Data.ItemIcons[itemId]
    end
    DetaurBar.Data.InitializeDB()
    if DetaurBarDB.iconCache and DetaurBarDB.iconCache[itemId] then
        return DetaurBarDB.iconCache[itemId]
    end
    local texture = select(10, GetItemInfo(itemId))
    if texture then
        if not DetaurBarDB.iconCache then DetaurBarDB.iconCache = {} end
        DetaurBarDB.iconCache[itemId] = texture
    end
    return texture
end

function DetaurBar.Data.GetRandomAlerts()
    DetaurBar.Data.InitializeDB()
    return DetaurBarDB.settings.randomAlerts or {}
end

function DetaurBar.Data.AddRandomAlert(name)
    DetaurBar.Data.InitializeDB()
    local alert = {
        id = tostring(time()) .. "_" .. tostring(math.random(1000, 9999)),
        name = name or "New Alert",
        intervalMinutes = 5,
        flashDuration = 3,
        flashColor = "YELLOW",
        playSound = false,
        sound = "RaidWarning",
    }
    table.insert(DetaurBarDB.settings.randomAlerts, alert)
    return alert
end

function DetaurBar.Data.DeleteRandomAlert(id)
    DetaurBar.Data.InitializeDB()
    local alerts = DetaurBarDB.settings.randomAlerts
    for i, alert in ipairs(alerts) do
        if alert.id == id then
            table.remove(alerts, i)
            if DetaurBarDB.settings.randomActiveAlertId == id then
                DetaurBarDB.settings.randomActiveAlertId = alerts[1] and alerts[1].id or nil
            end
            return true
        end
    end
    return false
end

function DetaurBar.Data.GetRandomActiveAlert()
    DetaurBar.Data.InitializeDB()
    local id = DetaurBarDB.settings.randomActiveAlertId
    if not id then return nil end
    for _, alert in ipairs(DetaurBarDB.settings.randomAlerts) do
        if alert.id == id then return alert end
    end
    return nil
end

function DetaurBar.Data.SetRandomActiveAlert(id)
    DetaurBar.Data.InitializeDB()
    DetaurBarDB.settings.randomActiveAlertId = id
end

function DetaurBar.Data.GetNoteCategories()
    DetaurBar.Data.InitializeDB()
    return DetaurBarDB.notes.categories
end

function DetaurBar.Data.NoteCategoryExists(name)
    DetaurBar.Data.InitializeDB()
    if not name then return false end
    for _, cat in ipairs(DetaurBarDB.notes.categories) do
        if cat == name then return true end
    end
    return false
end

function DetaurBar.Data.AddNoteCategory(name)
    DetaurBar.Data.InitializeDB()
    name = name:gsub("^%s*(.-)%s*$", "%1")
    if name == "" then return nil end
    for _, cat in ipairs(DetaurBarDB.notes.categories) do
        if cat:lower() == name:lower() then return nil end
    end
    table.insert(DetaurBarDB.notes.categories, name)
    DetaurBarDB.notes.data[name] = {}
    return name
end

function DetaurBar.Data.DeleteNoteCategory(name)
    DetaurBar.Data.InitializeDB()
    if #DetaurBarDB.notes.categories <= 1 then return false end
    for i, cat in ipairs(DetaurBarDB.notes.categories) do
        if cat == name then
            table.remove(DetaurBarDB.notes.categories, i)
            DetaurBarDB.notes.data[name] = nil
            return true
        end
    end
    return false
end

